P = 'cbse-g11-biology'


# ---------------------------------------------------------------- computed families

HIER = ['kingdom', 'phylum or division', 'class', 'order', 'family', 'genus', 'species']
TAXA = [  # organism, (kingdom, phylum/division, class, order, family, genus)  -- NCERT Table 1.1
    ('man', ['Animalia', 'Chordata', 'Mammalia', 'Primata', 'Hominidae', 'Homo']),
    ('housefly', ['Animalia', 'Arthropoda', 'Insecta', 'Diptera', 'Muscidae', 'Musca']),
    ('mango', ['Plantae', 'Angiospermae', 'Dicotyledonae', 'Sapindales', 'Anacardiaceae', 'Mangifera']),
    ('wheat', ['Plantae', 'Angiospermae', 'Monocotyledonae', 'Poales', 'Poaceae', 'Triticum']),
]


def taxon_rank(r):
    org, row = r.choice(TAXA)
    i = r.randrange(1, 6)
    val = row[i]
    rank = HIER[i]
    wrong = [h for h in HIER if h != rank and h != 'species']
    wrong = r.sample(wrong, 3)
    return mcq(f'In the classification of {org} (NCERT Table 1.1), “{val}” is the taxonomic category at the level of:', rank, wrong,
               f'{val} is the {rank} of {org}.', r)


def taxon_name(r):
    org, row = r.choice(TAXA)
    i = r.randrange(1, 6)
    good = row[i]
    pool = list(dict.fromkeys(x[1][i] for x in TAXA if x[1][i] != good))
    extra = {1: ['Mollusca', 'Gymnospermae', 'Annelida'], 2: ['Aves', 'Reptilia', 'Amphibia'], 3: ['Carnivora', 'Polymoniales', 'Lepidoptera'],
             4: ['Felidae', 'Solanaceae', 'Liliaceae'], 5: ['Panthera', 'Solanum', 'Felis']}[i]
    wrong = list(dict.fromkeys(pool + extra))
    wrong = [w for w in wrong if w != good]
    return mcq(f'To which {HIER[i]} does {org} belong?', good, r.sample(wrong, 3), f'{org.capitalize()}: {HIER[i]} {good}.', r)


