def gen_ploidy(r):
    parts = [('the protonema of a moss', 'n'), ('the capsule of a moss', '2n'), ('the prothallus of a fern', 'n'), ('the leaf of a fern', '2n'),
             ('the thallus of Marchantia', 'n'), ('the endosperm of a gymnosperm', 'n'), ('the endosperm of an angiosperm', '3n'),
             ('the zygote', '2n'), ('a spore', 'n'), ('the leaf of a moss gametophyte', 'n'), ('a megaspore mother cell', '2n'),
             ('the embryo of a seed', '2n'), ('a gamete', 'n'), ('the seta of a moss sporophyte', '2n')]
    p, k = r.choice(parts)
    opts = ['n', '2n', '3n', '4n']
    wrong = [o for o in opts if o != k]
    lab = {'n': 'haploid (n)', '2n': 'diploid (2n)', '3n': 'triploid (3n)', '4n': 'tetraploid (4n)'}
    return mcq(f'What is the ploidy of {p}?', lab[k], [lab[w] for w in wrong], f'{cap(p)} is {lab[k]}.', r)


